import pathlib,json,collections
r=pathlib.Path(r'D:\APK Works\HappyTidyRoom\analysis');c=json.loads((r/'mono/resources.assets_7861.json').read_text(encoding='utf8'));cnt=collections.Counter(x['subGroup'] for x in c['items']);g={x['value']:x for x in c['groups']};s={x['value']:x for x in c['subGroups']};print('COUNT',len(cnt),sum(cnt.values()),len(set(x['id'] for x in c['items'])),'nonremoved',sum(v for k,v in cnt.items() if not s[k]['removed']),'removed',[(s[k]['name'],v) for k,v in cnt.items() if s[k]['removed']]);print('ZERO ACTIVE',sum(not cnt[x['value']] for x in c['subGroups'] if not x['removed']));print('GROUPS',[(g[k]['folder'],sum(v for sg,v in cnt.items() if s[sg]['group']==k)) for k in sorted(set(x['group'] for x in c['items']))]);print('CATEGORIES','\n'.join(f'{k} | {g[s[k]["group"]]["folder"]} | {s[k]["folder"]} | {v}' for k,v in sorted(cnt.items())))
idx=json.loads((r/'mono-index.json').read_text(encoding='utf8'));print('BOOSTER SCENE',[(x['id'],x['file'],x['class']) for x in idx if any(k in x['class'] for k in ['Booster','QueueSlot']) and 'TMPro' not in x['class']][:30]);
